file.content:
# =============================================================================
# Traefik Route Module
# =============================================================================
# Generates and syncs Traefik dynamic configuration for an app.
# Each app can self-register its routes without modifying Traefik configs.
#
# Features:
# - Auto-generates YAML config from variables
# - Syncs to Traefik LXC via file-sync module
# - Supports internal (websecure) and public (web) routes
# - Health checks, middlewares, custom options
#
# Usage:
#   module "n8n_route" {
#     source = "../../modules/traefik-route"
#
#     app_name    = "n8n"
#     backend_url = "http://192.168.1.213:5678"
#
#     internal_domain = "n8n.homelab.rambtech.dev"
#     public_domain   = ""  # Optional
#
#     traefik_host         = "192.168.1.162"
#     ssh_private_key_path = var.ssh_private_key_path
#   }
# =============================================================================

terraform {
  required_providers {
    local = {
      source = "hashicorp/local"
    }
    filesync = {
      source = "darshan-rambhia/filesync"
    }
    ansible = {
      source  = "marshallford/ansible"
      version = "~> 0.9"
    }
  }
}

# -----------------------------------------------------------------------------
# Route Configuration Templates
# -----------------------------------------------------------------------------

locals {
  # Internal route (websecure with TLS)
  internal_route = var.internal_domain != "" ? {
    rule        = "Host(`${var.internal_domain}`)"
    entryPoints = var.internal_entrypoint
    service     = var.app_name
    tls = {
      certResolver = var.cert_resolver
    }
    middlewares = var.internal_middlewares
  } : null

  # Public route (supports both HTTP and HTTPS based on entrypoint)
  public_route = var.public_domain != "" ? merge(
    {
      rule        = "Host(`${var.public_domain}`)"
      entryPoints = var.public_entrypoint
      service     = var.app_name
      middlewares = var.public_middlewares
    },
    # Add TLS config if using websecure entrypoint
    contains(var.public_entrypoint, "websecure") ? {
      tls = {
        certResolver = var.cert_resolver
      }
    } : {}
  ) : null

  # Service configuration
  service_config = {
    loadBalancer = merge(
      {
        servers = [
          { url = var.backend_url }
        ]
      },
      var.health_check != null ? { healthCheck = var.health_check } : {}
    )
  }

  # Complete Traefik config
  traefik_config = {
    http = {
      routers = merge(
        local.internal_route != null ? { "${var.app_name}" = local.internal_route } : {},
        local.public_route != null ? { "${var.app_name}-public" = local.public_route } : {}
      )
      services = {
        "${var.app_name}" = local.service_config
      }
    }
  }

  # YAML output
  config_yaml = yamlencode(local.traefik_config)

  # Target path on Traefik LXC
  remote_config_path = "/config/dynamic/${var.app_name}.yml"
}

# -----------------------------------------------------------------------------
# Write Config to Temporary File
# -----------------------------------------------------------------------------

resource "local_file" "route_config" {
  content  = local.config_yaml
  filename = "${path.module}/.tmp/${var.app_name}.yml"

  # Create directory if needed
  provisioner "local-exec" {
    command = "mkdir -p ${path.module}/.tmp"
    when    = create
  }
}

# -----------------------------------------------------------------------------
# Sync to Traefik LXC using filesync provider
# -----------------------------------------------------------------------------

resource "filesync_file" "traefik_route" {
  source      = local_file.route_config.filename
  destination = local.remote_config_path
  host        = var.traefik_host

  # SSH configuration
  ssh_key_path = var.ssh_private_key_path

  # File permissions
  owner = "root"
  group = "root"
  mode  = "0644"

  depends_on = [local_file.route_config]
}

# -----------------------------------------------------------------------------
# Reload Traefik Configuration via Ansible
# -----------------------------------------------------------------------------
# Sends SIGUSR1 to Traefik process for graceful config reload (no restart)

resource "ansible_navigator_run" "reload_traefik" {
  count = var.reload_traefik ? 1 : 0

  depends_on = [filesync_file.traefik_route]

  triggers = {
    config_hash = local_file.route_config.content
  }

  execution_environment = {
    enabled = false  # Run ansible directly on host
  }

  ansible_options = {
    private_keys = [{
      name = "homelab"
      data = file(var.ssh_private_key_path)
    }]
  }

  playbook = <<-EOT
    - name: Reload Traefik configuration
      hosts: traefik
      gather_facts: no
      vars:
        app_name: ${var.app_name}

      tasks:
        # =====================================================================
        # Graceful Reload - SIGUSR1 triggers config reload without restart
        # =====================================================================
        - name: Send SIGUSR1 to Traefik for config reload
          ansible.builtin.command:
            cmd: docker exec traefik kill -USR1 1
          register: reload_result
          failed_when: reload_result.rc != 0
          changed_when: true

        - name: Display reload status
          ansible.builtin.debug:
            msg: "Traefik configuration reloaded for {{ app_name }}"
  EOT

  inventory = yamlencode({
    traefik = {
      hosts = {
        traefik = {
          ansible_host = var.traefik_host
          ansible_user = "root"
        }
      }
    }
  })
}

# -----------------------------------------------------------------------------
# Cleanup Temp File
# -----------------------------------------------------------------------------
# Note: Temp files are left in .tmp/ directory for debugging
# They can be safely deleted manually or via .gitignore

# =============================================================================
# Traefik Route Module - Variables
# =============================================================================

# -----------------------------------------------------------------------------
# Required Variables
# -----------------------------------------------------------------------------

variable "app_name" {
  description = "Name of the app (used for router/service names and config filename)"
  type        = string
}

variable "backend_url" {
  description = "Backend URL (e.g., http://192.168.1.213:5678)"
  type        = string
}

variable "traefik_host" {
  description = "Traefik LXC IP address"
  type        = string
}

variable "ssh_private_key_path" {
  description = "Path to SSH private key for Traefik LXC access"
  type        = string
}

# -----------------------------------------------------------------------------
# Domain Configuration
# -----------------------------------------------------------------------------

variable "internal_domain" {
  description = "Internal domain (e.g., n8n.homelab.rambtech.dev) - Leave empty to disable"
  type        = string
  default     = ""
}

variable "public_domain" {
  description = "Public domain (e.g., n8n.rambtech.dev) - Leave empty to disable"
  type        = string
  default     = ""
}

# -----------------------------------------------------------------------------
# Route Options
# -----------------------------------------------------------------------------

variable "internal_entrypoint" {
  description = "Traefik entrypoint for internal route"
  type        = list(string)
  default     = ["websecure"]
}

variable "public_entrypoint" {
  description = "Traefik entrypoint for public route"
  type        = list(string)
  default     = ["web"]
}

variable "internal_middlewares" {
  description = "List of middlewares for internal route"
  type        = list(string)
  default     = [ "security-headers", "internal-only" ]
}

variable "public_middlewares" {
  description = "List of middlewares for public route"
  type        = list(string)
  default     = ["public-security"]
}

variable "cert_resolver" {
  description = "TLS certificate resolver name"
  type        = string
  default     = "letsencrypt"
}

variable "health_check" {
  description = "Health check configuration (null to disable)"
  type = object({
    path     = optional(string, "/")
    interval = optional(string, "10s")
    timeout  = optional(string, "3s")
  })
  default = null
}

# -----------------------------------------------------------------------------
# Deployment Options
# -----------------------------------------------------------------------------

variable "reload_traefik" {
  description = "Send reload signal to Traefik after config update"
  type        = bool
  default     = true
}

variable "cleanup_temp_files" {
  description = "Delete temporary config files on destroy"
  type        = bool
  default     = true
}

# =============================================================================
# Shared Configuration
# =============================================================================
# This file is symlinked into each app directory to provide common variables
# and provider configuration. Each app has its own state file.
#
# Secret Management:
# - State encryption passphrase: Must remain as TF_VAR (needed before providers init)
# - All other secrets: Fetched from 1Password via onepassword provider
# =============================================================================

# -----------------------------------------------------------------------------
# State Encryption (Required as TF_VAR - runs before providers)
# -----------------------------------------------------------------------------

variable "state_encryption_passphrase" {
  description = "Passphrase for encrypting state files (from 1Password: op://homelab/opentofu/password)"
  type        = string
  sensitive   = true
}

# -----------------------------------------------------------------------------
# Proxmox Configuration
# -----------------------------------------------------------------------------

variable "proxmox_endpoint" {
  description = "Proxmox API endpoint URL"
  type        = string
  default     = "https://192.168.1.215:8006"
}

variable "proxmox_node" {
  description = "Proxmox node name"
  type        = string
  default     = "pve"
}

variable "proxmox_ssh_host" {
  description = "Proxmox host SSH address (for configuring privileged containers)"
  type        = string
  default     = "192.168.1.215"
}

# -----------------------------------------------------------------------------
# SSH Configuration
# -----------------------------------------------------------------------------

variable "ssh_private_key_path" {
  description = "Path to SSH private key"
  type        = string
  default     = "~/.ssh/homelab_ed25519"
}

variable "ssh_public_key_path" {
  description = "Path to SSH public key"
  type        = string
  default     = "~/.ssh/homelab_ed25519.pub"
}

# -----------------------------------------------------------------------------
# Storage & Network Defaults
# -----------------------------------------------------------------------------

variable "default_storage" {
  description = "Default storage for LXC containers"
  type        = string
  default     = "tank"
}

variable "default_bridge" {
  description = "Default network bridge"
  type        = string
  default     = "vmbr0"
}

variable "lxc_template" {
  description = "Default LXC template (base Debian)"
  type        = string
  default     = "local:vztmpl/debian-13-standard_13.1-2_amd64.tar.zst"
}

variable "lxc_template_docker" {
  description = "LXC template with Docker pre-installed"
  type        = string
  default     = "local:vztmpl/debian-13-docker_1.0_amd64.tar.zst"
}

# -----------------------------------------------------------------------------
# Domain Configuration
# -----------------------------------------------------------------------------

variable "domain_internal" {
  description = "Internal domain suffix"
  type        = string
  default     = "homelab.rambtech.dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]+[a-z0-9]$", var.domain_internal))
    error_message = "Internal domain must be a valid domain name (e.g., homelab.example.com)."
  }
}

variable "domain_public" {
  description = "Public domain"
  type        = string
  default     = "rambtech.dev"

  validation {
    condition     = can(regex("^[a-z0-9][a-z0-9.-]+[a-z0-9]$", var.domain_public))
    error_message = "Public domain must be a valid domain name (e.g., example.com)."
  }
}

# -----------------------------------------------------------------------------
# Cloudflare Configuration (IDs only - tokens from 1Password)
# -----------------------------------------------------------------------------

variable "cloudflare_account_id" {
  description = "Cloudflare account ID"
  type        = string
  default     = ""
}

variable "cloudflare_zone_id" {
  description = "Cloudflare zone ID"
  type        = string
  default     = ""
}

variable "cloudflare_tunnel_id" {
  description = "Cloudflare tunnel ID"
  type        = string
  default     = ""
}

# -----------------------------------------------------------------------------
# Computed Locals
# -----------------------------------------------------------------------------

locals {
  ssh_public_key = file(var.ssh_public_key_path)
}

